if __name__ == "__main__":
    revise_domain("475", "475_moon_civilization", MOON,
                  "Moon civilization through the gap between exploration missions and sustained residence, lunar logistics, physical hazards, research, and governance.",
                  "NASA Moon-to-Mars architecture and mission records, subsystem test results, lunar measurements, program budgets, and Outer Space Treaty",
                  "Name site, mission stage, population, and duration. A design or resource detection is not an operational settlement.")
    revise_domain("476", "476_mars_civilization", MARS,
                  "Mars civilization through measured hazards, human mission dependencies, planetary protection, and speculative settlement claims.",
                  "NASA human-spaceflight hazard research and Moon-to-Mars architecture, robotic mission results, technical trials, planetary-protection guidance, and Outer Space Treaty",
                  "Name mission, site, crew, and timescale. Earth analogs and robotic demonstrations do not prove a safe human settlement.")
    revise_domain("477", "477_space_civilization", SPACE,
                  "Space civilization through present orbital habitation, Earth dependencies, health and social limits, law, and conditional expansion.",
                  "NASA space-station life-support and operations records, human research, partnership agreements, orbital safety data, and Outer Space Treaty",
                  "Name orbit or destination and duration. A research station is not a self-sufficient civilization.")
    rows = audit()
    print(f"Plans: {len(rows)}; reviewed question designs: {sum(r['status'] == 'editorial_question_reviewed' for r in rows)}")
